#!/usr/bin/env python3
"""Render the approved capability/support matrix and original-package disposition."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

def render():
    caps = json.loads((ROOT/'catalog/asset-management-capabilities.json').read_text())['capabilities']
    moves = json.loads((ROOT/'catalog/asset-management-migrations.json').read_text())['migrations']
    matrix = ['# Asset management support matrix', '',
        'Generated by `tools/build_asset_management_index.py` from the approved capability manifest. '
        'There are 64 target AM capabilities and four shared capabilities moved out of AM. '
        'Phase4 implements all64 AM packages with the bounded scopes below; package presence does not establish complete professional coverage.', '',
        '`bounded-native` means documented offline methods are implemented; `implemented-router` '
        'means declared-intent route planning; `planned` means unavailable. '
        'All entries remain draft-only, without authenticated external access or professional acceptance. '
        'A renamed package does not gain the broader methods implied by its future role.', '',
        '| ID | Capability / owner | Current support | Implemented scope or planned job |',
        '|---|---|---|---|']
    for row in caps:
        label = row['name']
        if row['support_status'] != 'planned':
            label = f"[{label}](../../{row['path']}/SKILL.md)"
        matrix.append(f"| {row['id']} | {label}<br>{row['category']} | {row['support_status']} | {row['implementation_scope'].replace('|', '/')} |")
    matrix += ['', 'Common evidence wrappers are available only for the explicitly registered native identity/date adapters. '
        'See the [contract and packaging guide](CONTRACTS-AND-PACKAGING.md). A native method can be usable '
        'while a cross-skill artifact adapter is unsupported.', '']
    disposition = ['# Original package disposition', '',
        'Every original AM package has one canonical owner. Legacy names and old paths resolve through '
        '`tools/resolve_skill.py`; aliases are metadata, not duplicate workflow packages. '
        'Merged aliases return a required mode. Wrap the old native input as `{"mode": "…", "input": {...}}` '
        'for the canonical merged entrypoint.', '',
        '| Original package | Canonical owner / package | Disposition | Mode |', '|---|---|---|---|']
    for row in moves:
        if row['old_path'].startswith('skills/asset-management/'):
            disposition.append(f"| {row['old_name']} | {row['category']} / [{row['new_name']}](../../{row['new_path']}/SKILL.md) | {row['action']} | {row['mode'] or '—'} |")
    disposition += ['', 'The original category migration recorded 25 former Investment Banking & Research packages: '
        '16 moved to Investment Research and nine transaction-specific packages moved to Investment Banking. '
        'Two credit capabilities moved from AM made 18 Investment Research packages at that checkpoint. '
        'IR Phase 1 subsequently renamed the issuer capital-structure mapper and moved generic document comparison '
        'to Data, AI & Model Governance; this registry records the terminal owners. '
        'See [current IR support](../investment-research/support-matrix.md) for installed and planned methods.', '']
    return {'docs/asset-management/SUPPORT-MATRIX.md': '\n'.join(matrix),
            'docs/asset-management/DISPOSITION.md': '\n'.join(disposition)}

def run(check=False):
    errors=[]
    for name,text in render().items():
        path=ROOT/name
        if check:
            if not path.exists() or path.read_text()!=text: errors.append(name+' differs')
        else: path.write_text(text)
    return errors

if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--check',action='store_true')
    errors=run(parser.parse_args().check)
    for error in errors:print(error)
    print('Asset management index: '+('FAIL' if errors else 'PASS'))
    raise SystemExit(bool(errors))
